css:
.cascadia-sim-container {
    padding: 24px;
    background: linear-gradient(180deg, #0a1530 0%, #0f1d3d 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #e8eef9;
}
.cascadia-sim-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: linear-gradient(135deg, rgba(255,107,53,0.12), rgba(0,212,170,0.06));
    border: 1px solid rgba(255,107,53,0.3);
    border-radius: 12px;
    padding: 24px 28px;
    margin-bottom: 24px;
}
.cascadia-sim-brand {
    display: flex;
    align-items: center;
    gap: 18px;
}
.cascadia-sim-logo {
    width: 64px;
    height: 64px;
    border-radius: 50%;
    background: linear-gradient(135deg, #ff6b35, #f9a26c);
    color: #0a1530;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 800;
    font-size: 1.05rem;
    letter-spacing: 0.05em;
    box-shadow: 0 8px 24px rgba(255,107,53,0.35);
}
.cascadia-sim-titlewrap h1 {
    margin: 0;
    font-size: 1.6rem;
    font-weight: 700;
    color: #ffffff;
    letter-spacing: 0.02em;
}
.cascadia-sim-subtitle {
    color: #f9a26c;
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    margin-top: 4px;
}
.cascadia-sim-period-counter {
    background: #0a1530;
    border: 1px solid #2a3f6e;
    border-radius: 8px;
    padding: 12px 20px;
    color: #8b9bb8;
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
}
.cascadia-sim-period-counter span:nth-child(2),
.cascadia-sim-period-counter span:nth-child(4) {
    color: #00d4aa;
    font-weight: 700;
    font-size: 1.05rem;
    margin: 0 4px;
}
.cascadia-sim-briefing {
    background: rgba(20,34,63,0.6);
    border-left: 4px solid #ff6b35;
    border-radius: 8px;
    padding: 20px 24px;
    margin-bottom: 24px;
}
.cascadia-sim-briefing-label {
    color: #ff6b35;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    margin-bottom: 6px;
    font-weight: 600;
}
.cascadia-sim-briefing-title {
    color: #ffffff;
    font-size: 1.15rem;
    font-weight: 700;
    margin-bottom: 8px;
}
.cascadia-sim-briefing-text {
    color: #cbd5e1;
    font-size: 0.95rem;
    line-height: 1.55;
}
.cascadia-sim-briefing-text strong {
    color: #f9a26c;
}
.cascadia-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
    gap: 14px;
    margin-bottom: 28px;
}
.cascadia-sim-kpi-card {
    background: #14223f;
    border: 1px solid #1f2d4f;
    border-radius: 10px;
    padding: 18px 16px;
    position: relative;
    overflow: hidden;
    transition: transform 0.15s ease, border-color 0.15s ease;
}
.cascadia-sim-kpi-card:hover {
    transform: translateY(-2px);
    border-color: #2d3f6e;
}
.cascadia-sim-kpi-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 3px;
}
.cascadia-sim-kpi-cash::before { background: #00d4aa; }
.cascadia-sim-kpi-stms::before { background: #ff6b35; }
.cascadia-sim-kpi-sport::before { background: #4ade80; }
.cascadia-sim-kpi-brand::before { background: #f9a26c; }
.cascadia-sim-kpi-gameday::before { background: #60a5fa; }
.cascadia-sim-kpi-valuation::before { background: linear-gradient(90deg, #ff6b35, #00d4aa); }
.cascadia-sim-kpi-label {
    color: #8b9bb8;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    margin-bottom: 8px;
    font-weight: 600;
}
.cascadia-sim-kpi-value {
    font-size: 1.65rem;
    font-weight: 700;
    color: #ffffff;
    line-height: 1.1;
}
.cascadia-sim-kpi-cash .cascadia-sim-kpi-value { color: #00d4aa; }
.cascadia-sim-kpi-stms .cascadia-sim-kpi-value { color: #ff6b35; }
.cascadia-sim-kpi-sport .cascadia-sim-kpi-value { color: #4ade80; }
.cascadia-sim-kpi-brand .cascadia-sim-kpi-value { color: #f9a26c; }
.cascadia-sim-kpi-gameday .cascadia-sim-kpi-value { color: #60a5fa; }
.cascadia-sim-kpi-valuation .cascadia-sim-kpi-value { color: #ffffff; }
.cascadia-sim-kpi-detail {
    color: #6b7a99;
    font-size: 0.7rem;
    margin-top: 5px;
}
.cascadia-sim-controls {
    background: #14223f;
    border: 1px solid #1f2d4f;
    border-radius: 12px;
    padding: 24px;
    margin-bottom: 28px;
}
.cascadia-sim-controls h3 {
    color: #ffffff;
    font-size: 1.05rem;
    margin: 0 0 18px 0;
    padding-bottom: 12px;
    border-bottom: 1px solid #1f2d4f;
    letter-spacing: 0.02em;
}
.cascadia-sim-control-group {
    margin-bottom: 18px;
}
.cascadia-sim-control-row {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
    gap: 16px;
    margin-bottom: 18px;
}
.cascadia-sim-control-group label {
    display: block;
    color: #cbd5e1;
    font-size: 0.85rem;
    font-weight: 600;
    margin-bottom: 6px;
    letter-spacing: 0.03em;
}
.cascadia-sim-controls input[type="number"],
.cascadia-sim-controls select {
    background: #0a1530;
    border: 1px solid #2a3f6e;
    color: #e8eef9;
    border-radius: 6px;
    padding: 10px 12px;
    width: 100%;
    font-size: 0.95rem;
    font-family: inherit;
}
.cascadia-sim-controls select option {
    background: #14223f;
    color: #e8eef9;
}
.cascadia-sim-controls input[type="number"]:focus,
.cascadia-sim-controls select:focus {
    outline: none;
    border-color: #00d4aa;
    box-shadow: 0 0 0 2px rgba(0,212,170,0.2);
}
.cascadia-sim-hint {
    color: #6b7a99;
    font-size: 0.75rem;
    margin-top: 5px;
    line-height: 1.4;
}
.cascadia-sim-actions {
    display: flex;
    gap: 12px;
    margin-top: 18px;
    flex-wrap: wrap;
}
.cascadia-sim-submit {
    background: linear-gradient(135deg, #ff6b35, #f9a26c) !important;
    border: none !important;
    color: #0a1530 !important;
    font-weight: 700 !important;
    padding: 12px 28px !important;
    border-radius: 8px !important;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    font-size: 0.85rem;
    box-shadow: 0 4px 16px rgba(255,107,53,0.3);
    transition: transform 0.15s ease, box-shadow 0.15s ease;
}
.cascadia-sim-submit:hover {
    transform: translateY(-1px);
    box-shadow: 0 6px 20px rgba(255,107,53,0.45);
    color: #0a1530 !important;
}
#undoBtn {
    background: transparent !important;
    border: 1px solid #2a3f6e !important;
    color: #8b9bb8 !important;
    border-radius: 8px !important;
    padding: 10px 20px !important;
    font-size: 0.8rem;
}
#undoBtn:hover {
    border-color: #ff6b35 !important;
    color: #ff6b35 !important;
}
.cascadia-sim-history-block {
    background: #14223f;
    border: 1px solid #1f2d4f;
    border-radius: 12px;
    padding: 20px 24px;
    margin-bottom: 28px;
    overflow-x: auto;
}
.cascadia-sim-history-block h3 {
    color: #ffffff;
    font-size: 1rem;
    margin: 0 0 14px 0;
    letter-spacing: 0.02em;
}
.cascadia-sim-history-table {
    color: #cbd5e1 !important;
    font-size: 0.85rem;
    background: transparent !important;
    margin-bottom: 0 !important;
}
.cascadia-sim-history-table thead {
    background: #0a1530;
}
.cascadia-sim-history-table thead th {
    color: #ff6b35 !important;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    font-size: 0.7rem;
    border-bottom: 1px solid #2a3f6e !important;
    border-top: none !important;
    padding: 10px 12px !important;
    font-weight: 600;
}
.cascadia-sim-history-table tbody tr {
    background: transparent !important;
}
.cascadia-sim-history-table tbody tr:nth-child(even) {
    background: rgba(255,255,255,0.02) !important;
}
.cascadia-sim-history-table tbody td {
    border-color: #1f2d4f !important;
    padding: 9px 12px !important;
    color: #cbd5e1 !important;
}
.cascadia-sim-charts {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
}
.cascadia-sim-chart-card {
    background: #14223f;
    border: 1px solid #1f2d4f;
    border-radius: 12px;
    padding: 20px;
    height: 340px;
    display: flex;
    flex-direction: column;
}
.cascadia-sim-chart-card h4 {
    color: #ffffff;
    font-size: 0.9rem;
    margin: 0 0 12px 0;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    color: #f9a26c;
}
.cascadia-sim-chart-card canvas {
    flex: 1;
    max-height: 260px !important;
}
@media (max-width: 768px) {
    .cascadia-sim-container { padding: 14px; }
    .cascadia-sim-header { flex-direction: column; gap: 16px; align-items: flex-start; }
    .cascadia-sim-charts { grid-template-columns: 1fr; }
    .cascadia-sim-control-row { grid-template-columns: 1fr; }
    .cascadia-sim-titlewrap h1 { font-size: 1.3rem; }
    .cascadia-sim-kpi-value { font-size: 1.4rem; }
}
.cascadia-sim-container select:focus-visible,
.cascadia-sim-container input:focus-visible,
.cascadia-sim-container button:focus-visible,
.cascadia-sim-container a:focus-visible {
    outline: 3px solid #00d4aa;
    outline-offset: 2px;
}

.cascadia-sim-completion {
    background: #10192f;
    border: 1px solid #1f2d4f;
    border-left: 4px solid #00d4aa;
    border-radius: 4px;
    padding: 20px 24px;
    margin-bottom: 24px;
    color: #e2e8f0;
}

.cascadia-sim-completion-title {
    font-size: 1.1rem;
    font-weight: 700;
    color: #ffffff;
    margin: 0 0 10px 0;
}

.cascadia-sim-completion-insights li {
    margin-bottom: 8px;
    line-height: 1.5;
}

@media (prefers-reduced-motion: reduce) {
    .cascadia-sim-container *,
    .cascadia-sim-container *::before,
    .cascadia-sim-container *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
        scroll-behavior: auto !important;
    }
}

/* EQIL 2026-11-11: debrief discussion questions */
.cascadia-sim-completion-questions { margin: 6px 0 0 18px; padding: 0; }
.cascadia-sim-completion-questions li { margin-bottom: 6px; }

