                        { value: 'heroOpen', labelKey: 'opt_heroOpen' }
                    ]
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: 105000,
                    stms: 9840,
                    pipeline: 19200,
                    sportingScore: 60,
                    brandScore: 50,
                    gamedayReadiness: 30,
                    corvistaReliability: 30,
                    cumulativeRevenue: 0,
                    cumulativeCost: 0,
                    rngSeed: 0x9E3779B9,
                    dpFrameLocked: null,
                    cashHistory: [],
                    stmHistory: [],
                    sportingHistory: [],
                    brandHistory: [],
                    gamedayHistory: [],
                    valuationHistory: [],
                    revenueHistory: [],
                    costHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    strategicChoice: '',
                    stmInvestment: 500,
                    gamedayInvestment: 300,
                    corvistaInvestment: 200
                };
            }
            this._bindRepaint();
            this._updateBriefing(state);
        }

        _bindRepaint() {
            if (this._cascadiaBound) return;
            this._cascadiaBound = true;
            const self = this;
            const repaint = function() {
                try {
                    if (window.mySimulation && window.mySimulation.state) self._updateBriefing(window.mySimulation.state);
                } catch (e) { /* silent */ }
            };
            document.addEventListener('express:langchanged', repaint);
            try {
                const bus = window.mySimulation && window.mySimulation.eventBus;
                if (bus && typeof bus.on === 'function') {
                    bus.on('language:changed', repaint);
                    bus.on('period:undone', repaint);
                }
            } catch (e) { /* silent */ }
        }

        _periodOf(state) {
            const shownPeriod = (state && state.currentPeriod) || 1;
            const played = state && Array.isArray(state.history) ? state.history.length + 1 : 1;
            return Math.min(Math.max(shownPeriod, played), this.WINDOWS.length + 1);
        }

        validateDecisions(decisions) {
            const sel = document.getElementById('strategicChoice');
            if (sel) decisions.strategicChoice = sel.value;

            const stmIn = document.getElementById('stmInvestment');
            if (stmIn) decisions.stmInvestment = parseFloat(stmIn.value) || 0;

            const gdIn = document.getElementById('gamedayInvestment');
            if (gdIn) decisions.gamedayInvestment = parseFloat(gdIn.value) || 0;

            const apIn = document.getElementById('corvistaInvestment');
            if (apIn) decisions.corvistaInvestment = parseFloat(apIn.value) || 0;

            const curWin = this.WINDOWS[this._periodOf(window.mySimulation.state) - 1];
            if (curWin && !curWin.options.some(function(o) { return o.value === decisions.strategicChoice; })) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('choice_warning'), 'warning'
                );
                return false;
            }

            if (decisions.stmInvestment < 0 || decisions.gamedayInvestment < 0 || decisions.corvistaInvestment < 0) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('negative_warning'), 'warning'
                );
                return false;
            }

            const totalSpend = decisions.stmInvestment + decisions.gamedayInvestment + decisions.corvistaInvestment;
            const cash = window.mySimulation.state.domainState.cash;

            if (totalSpend > cash + 8000) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('cash_warning'), 'warning'
                );
                return false;
            }

            return true;
        }

        _rng(ds) {
            if (ds.rngSeed === undefined || ds.rngSeed === null) ds.rngSeed = 0x9E3779B9;
            var x = (ds.rngSeed + 0x6D2B79F5) | 0;
            ds.rngSeed = x;
            var t = Math.imul(x ^ (x >>> 15), 1 | x);
            t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
            return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const period = state.currentPeriod;

            if (period === 1) {
                ds.dpFrameLocked = d.strategicChoice;
            }

            const choiceImpact = this._getChoiceImpact(period, d.strategicChoice);

            const stmConvBoost = Math.round((d.stmInvestment / 100) * 18 + this._rng(ds) * 50);
            const gamedayBoost = (d.gamedayInvestment / 100) * 0.9 + this._rng(ds) * 1.5;
            const corvistaBoost = (d.corvistaInvestment / 100) * 0.85 + this._rng(ds) * 1.2;

            const baseConvSchedule = [240, 320, 420, 580, 720, 880, 1040, 0];
            const baseConv = baseConvSchedule[period - 1] || 0;

            const stmDelta = (choiceImpact.stmDelta || 0);
            const stmGainRaw = baseConv + stmConvBoost + stmDelta;
            const stmGain = Math.max(-400, Math.min(ds.pipeline, stmGainRaw));
            ds.stms = Math.max(0, ds.stms + stmGain);
            ds.pipeline = Math.max(0, ds.pipeline - Math.max(0, stmGain));

            ds.sportingScore = Math.max(0, Math.min(100, ds.sportingScore + (choiceImpact.sportingDelta || 0)));
            ds.brandScore = Math.max(0, Math.min(100, ds.brandScore + corvistaBoost + (choiceImpact.brandDelta || 0)));
            ds.corvistaReliability = Math.max(0, Math.min(100, ds.corvistaReliability + corvistaBoost + (choiceImpact.corvistaDelta || 0)));
            ds.gamedayReadiness = Math.max(0, Math.min(100, ds.gamedayReadiness + gamedayBoost + (choiceImpact.gamedayDelta || 0)));

            const stmCashThisPeriod = Math.max(0, stmGain) * 1650 / 1000;

            let sponsorCash = 0;
            if (period === 4) sponsorCash = (ds.brandScore / 100) * 3500;
            else if (period === 5) sponsorCash = (ds.brandScore / 100) * 2200;
            else if (period === 6) sponsorCash = (ds.brandScore / 100) * 4800;
            else if (period === 7) sponsorCash = (ds.brandScore / 100) * 2200;

            let corvistaDistribution = 0;
            let suiteCash = 0;
            let matchdayRev = 0;
            let sumDist = 0;

            if (period >= 4 && period <= 7) {
                const suiteRate = 0.18 + (ds.brandScore / 1500);
                suiteCash = 6700 * suiteRate;
            }

            if (period === 8) {
                const corvistaFactor = 7500 + (ds.corvistaReliability / 100) * 1500;
                corvistaDistribution = corvistaFactor;

                const fillRateBase = Math.min(1.0, (ds.stms + 4500) / 23500);
                const fillRate = fillRateBase * (0.85 + ds.brandScore / 600);
                const perCap = 26 + (ds.gamedayReadiness / 100) * 8;
                matchdayRev = 23500 * Math.min(1.0, fillRate) * perCap * 17 / 1000;

                sumDist = 4200 + 1800 + 2000;
            }

            const periodRevenue = stmCashThisPeriod + sponsorCash + corvistaDistribution + suiteCash + matchdayRev + sumDist;

            const baseOpCostPerPeriod = 83200 / 8;
            const sportingExtra = (choiceImpact.cashCost || 0);
            const investments = d.stmInvestment + d.gamedayInvestment + d.corvistaInvestment;
            const periodCost = baseOpCostPerPeriod + sportingExtra + investments;

            ds.cash = Math.round(ds.cash + periodRevenue - periodCost);
            ds.cumulativeRevenue += periodRevenue;
            ds.cumulativeCost += periodCost;

            const compositeScore = (ds.sportingScore * 0.25) + (ds.brandScore * 0.30) + (ds.gamedayReadiness * 0.25) + (ds.corvistaReliability * 0.20);
            const stmRatio = Math.min(1.5, ds.stms / 14000);
            const multiple = 3.5 + (compositeScore / 100) * 3.0;
            const projectedAnnualRevenue = 98100 * stmRatio * (0.7 + compositeScore / 333);
            const valuation = Math.round(projectedAnnualRevenue * multiple / 1000);

            ds.cashHistory.push(ds.cash);
            ds.stmHistory.push(ds.stms);
            ds.sportingHistory.push(Math.round(ds.sportingScore));
            ds.brandHistory.push(Math.round(ds.brandScore));
            ds.gamedayHistory.push(Math.round(ds.gamedayReadiness));
            ds.valuationHistory.push(valuation);
            ds.revenueHistory.push(Math.round(periodRevenue));
            ds.costHistory.push(Math.round(periodCost));

            // Grade persisted every window: the same composite the summary computes, on the run so far.
            const revToDate = ds.revenueHistory.reduce(function(a, b) { return a + b; }, 0);
            const costToDate = ds.costHistory.reduce(function(a, b) { return a + b; }, 0);
            const runningScore = this._composite(valuation, revToDate - costToDate, ds.stms,
                Math.round(ds.gamedayReadiness), Math.round(ds.corvistaReliability));
            ds.performance = { overallScore: runningScore, tier: this._bandOf(valuation) };

            const self = this;
            const nextPeriod = period + 1;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: nextPeriod });
            }, 500);

            return {
                period: period,
                strategicChoice: d.strategicChoice,
                strategicChoiceLabel: this._getChoiceLabel(d.strategicChoice),
                stmGain: stmGain,
                stmsTotal: ds.stms,
                periodRevenue: Math.round(periodRevenue),
                periodCost: Math.round(periodCost),
                periodNet: Math.round(periodRevenue - periodCost),
                sportingScore: Math.round(ds.sportingScore),
                brandScore: Math.round(ds.brandScore),
                gamedayReadiness: Math.round(ds.gamedayReadiness),
                corvistaReliability: Math.round(ds.corvistaReliability),
                valuation: valuation,
                cash: ds.cash,
                stmInvestment: d.stmInvestment,
                gamedayInvestment: d.gamedayInvestment,
                corvistaInvestment: d.corvistaInvestment,
                overallScore: runningScore,
                score: runningScore
            };
        }

