        _getChoiceLabel(choice) {
            const t = window.mySimulation && window.mySimulation.t ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };
            const map = {
                frameA: 'opt_frameA', frameB: 'opt_frameB', frameC: 'opt_frameC',
                matchCash: 'opt_matchCash', matchEquity: 'opt_matchEquity', holdTerms: 'opt_holdTerms', walkAway: 'opt_walkAway',
                aggressiveTAM: 'opt_aggressiveTAM', balancedTAM: 'opt_balancedTAM', leanTAM: 'opt_leanTAM',
                compressed: 'opt_compressed', standardOpen: 'opt_standardOpen', fullCalendar: 'opt_fullCalendar',
                standardCorvista: 'opt_standardCorvista', enhancedCorvista: 'opt_enhancedCorvista', featuredCorvista: 'opt_featuredCorvista',
                directSupporters: 'opt_directSupporters', yieldedSupporters: 'opt_yieldedSupporters', corporateSupporters: 'opt_corporateSupporters',
                premiumValueAdd: 'opt_premiumValueAdd', modestDiscount: 'opt_modestDiscount', steepDiscount: 'opt_steepDiscount',
                conservativeOpen: 'opt_conservativeOpen', standardOpener: 'opt_standardOpener', heroOpen: 'opt_heroOpen'
            };
            return map[choice] ? t(map[choice]) : choice;
        }

        _updateBriefing(state) {
            const period = this._periodOf(state);
            const t = window.mySimulation && window.mySimulation.t ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };
            this._updateChartAlt(t);
            const titleEl = document.getElementById('briefingTitle');
            const textEl = document.getElementById('briefingText');
            const sel = document.getElementById('strategicChoice');

            if (period > this.WINDOWS.length) {
                if (titleEl) titleEl.innerHTML = t('finished_title');
                if (textEl) textEl.innerHTML = t('finished_text');
                if (sel) { sel.innerHTML = ''; sel.disabled = true; }
                ['stmInvestment', 'gamedayInvestment', 'corvistaInvestment'].forEach(function(id) {
                    const el = document.getElementById(id);
                    if (el) el.disabled = true;
                });
                const row = document.querySelector('.cascadia-sim-actions');
                if (row) row.style.display = 'none';
                const sb = document.getElementById('nextPeriodBtn');
                if (sb) { sb.disabled = true; sb.setAttribute('aria-disabled', 'true'); }
                return;
            }

            const win = this.WINDOWS[period - 1];
            if (titleEl) titleEl.innerHTML = t(win.titleKey);
            if (textEl) textEl.innerHTML = t(win.textKey);

            if (sel) {
                const shown = sel.value;
                sel.innerHTML = '';
                sel.disabled = false;
                const ph = document.createElement('option');
                ph.value = '';
                ph.disabled = true;
                ph.textContent = t('choice_placeholder');
                sel.appendChild(ph);
                win.options.forEach(function(opt) {
                    const o = document.createElement('option');
                    o.value = opt.value;
                    o.textContent = t(opt.labelKey);
                    sel.appendChild(o);
                });
                const stored = state && state.decisions ? state.decisions.strategicChoice : null;
                const has = function(v) { return win.options.some(function(o) { return o.value === v; }); };
                sel.value = has(shown) ? shown : (has(stored) ? stored : '');
            }
            if (state && state.domainState) this._syncControlsFromDecisions(state);
        }

        _updateChartAlt(t) {
            const fin = document.getElementById('financialChart');
            if (fin) { fin.setAttribute('role', 'img'); fin.setAttribute('aria-label', t('chart_revenue_alt')); }
            const kpi = document.getElementById('kpiChart');
            if (kpi) { kpi.setAttribute('role', 'img'); kpi.setAttribute('aria-label', t('chart_kpi_alt')); }
        }

        _syncControlsFromDecisions(state) {
            const d = state && state.decisions;
            if (!d) return;
            ['stmInvestment', 'gamedayInvestment', 'corvistaInvestment'].forEach(function(id) {
                const el = document.getElementById(id);
                if (el && d[id] !== undefined && d[id] !== null) el.value = String(d[id]);
            });
