        getHint(state, results) {
            if (!results) return null;
            if (state.domainState.cash < 0) return window.mySimulation.t('hint_negative_cash');
            if (state.currentPeriod >= 4 && state.domainState.stms < state.currentPeriod * 1400) {
                return window.mySimulation.t('hint_stm_pacing');
            }
            if (state.currentPeriod >= 5 && state.domainState.corvistaReliability < 35) {
                return window.mySimulation.t('hint_corvista_low');
            }
            if (state.currentPeriod >= 6 && state.domainState.gamedayReadiness < 50) {
                return window.mySimulation.t('hint_gameday_low');
            }
            if (state.currentPeriod >= 3 && state.domainState.brandScore < 40) {
                return window.mySimulation.t('hint_brand_low');
            }
            return null;
        }

