            return [
                { key: 'results.strategicChoice', label: 'Choice', i18nKey: 'col_choice', formatter: (v) => this._getChoiceLabel(v) },
                { key: 'results.stmsTotal', label: 'STMs', i18nKey: 'col_stms', formatter: (v) => Math.round(v).toLocaleString() },
                { key: 'results.sportingScore', label: 'Sport', i18nKey: 'col_sport', formatter: (v) => Math.round(v) },
                { key: 'results.brandScore', label: 'Brand', i18nKey: 'col_brand', formatter: (v) => Math.round(v) },
                { key: 'results.gamedayReadiness', label: 'Gameday', i18nKey: 'col_gameday', formatter: (v) => Math.round(v) },
                { key: 'results.periodNet', label: 'Net (USD K)', i18nKey: 'col_net', formatter: (v) => (v >= 0 ? '+' : '') + Math.round(v).toLocaleString() },
                { key: 'results.valuation', label: '5-Yr Val (USD M)', i18nKey: 'col_valuation', formatter: (v) => '$' + Math.round(v) + 'M' }
            ];
        }

        _composite(finalValuation, ebitda, finalStms, gameday, corvista) {
            var v = finalValuation || 0;
            var score;
            if (v >= 1200) score = 100;
            else if (v >= 400) score = 40 + ((v - 400) / 800) * 60;
            else score = Math.max(0, (v / 400) * 40);
            if ((ebitda || 0) < 5000) score = Math.min(score, 70);
            if ((finalStms || 0) < 11000) score = Math.min(score, 75);
            if ((gameday || 0) < 60) score = Math.min(score, 80);
            if ((corvista || 0) < 50) score = Math.min(score, 85);
            return Math.max(0, Math.min(100, Math.round(score)));
        }

        _bandOf(valuation) {
            if (valuation > 1000) return 'top';
            if (valuation > 800) return 'strong';
            if (valuation > 600) return 'envelope';
            if (valuation > 400) return 'below';
            return 'atrisk';
        }

        _fmtDelta(v) {
            const n = Math.round(v);
            return (n >= 0 ? '+' : '') + n;
        }

        // What the run did, read from its history: each entry is a key plus the values it prints.
        _runFindings(history) {
            const out = [];
            let stm = 0, gd = 0, ap = 0;
            const picks = {};
            for (let i = 0; i < history.length; i++) {
                const r = history[i].results || {};
                const dec = history[i].decisions || {};
                stm += Number(r.stmInvestment !== undefined ? r.stmInvestment : dec.stmInvestment) || 0;
                gd += Number(r.gamedayInvestment !== undefined ? r.gamedayInvestment : dec.gamedayInvestment) || 0;
                ap += Number(r.corvistaInvestment !== undefined ? r.corvistaInvestment : dec.corvistaInvestment) || 0;
                picks[r.strategicChoice] = true;
            }
            const total = stm + gd + ap;
            const lowLine = 200 * history.length;
            if (total < lowLine) out.push({ key: 'mis_cash' });
            else if (stm / total >= 0.7) out.push({ key: 'mis_conversion', pct: Math.round(100 * stm / total) });
            if (picks.compressed) out.push({ key: 'mis_compressed' });
            if (picks.directSupporters) out.push({ key: 'mis_control' });
            if (picks.steepDiscount) out.push({ key: 'mis_discount' });
            return out;
        }

        _turningPoint(history) {
            let best = null, worst = null;
            for (let i = 1; i < history.length; i++) {
                const cur = history[i].results || {};
                const prev = history[i - 1].results || {};
                const delta = (cur.valuation || 0) - (prev.valuation || 0);
                const row = { window: i + 1, choice: cur.strategicChoice, delta: delta };
                if (!best || delta > best.delta) best = row;
                if (!worst || delta < worst.delta) worst = row;
            }
            if (!best || !worst || best.window === worst.window) return null;
            return { best: best, worst: worst };
        }

        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            const t = window.mySimulation.t.bind(window.mySimulation);
            const last = history[history.length - 1];
            const lastResult = last.results || {};
            const finalValuation = lastResult.valuation || 0;
            const totalRevenue = history.reduce((s, h) => s + ((h.results && h.results.periodRevenue) || 0), 0);
            const totalCost = history.reduce((s, h) => s + ((h.results && h.results.periodCost) || 0), 0);
            const ebitda = totalRevenue - totalCost;
            const finalStms = lastResult.stmsTotal || 0;

            const band = this._bandOf(finalValuation);

            const composite = this._composite(finalValuation, ebitda, finalStms,
                lastResult.gamedayReadiness, lastResult.corvistaReliability);

            const findings = this._runFindings(history);
            const turning = this._turningPoint(history);
            const insights = [t('sum_' + band)];
            for (let i = 0; i < findings.length; i++) {
                insights.push(t(findings[i].key)
                    .replace('{pct}', findings[i].pct)
                    .replace('{cash}', ((lastResult.cash || 0) / 1000).toFixed(1)));
            }
            if (finalStms < 11000) insights.push(t('sum_stm_short'));
            if (ebitda < 5000) insights.push(t('sum_ebitda_low'));
            if (lastResult.corvistaReliability < 50) insights.push(t('sum_corvista_low'));
            if (lastResult.gamedayReadiness < 60) insights.push(t('sum_gameday_low'));

            return {
                finalValuation,
                totalRevenue: Math.round(totalRevenue),
                totalCost: Math.round(totalCost),
                ebitda: Math.round(ebitda),
                finalStms: finalStms,
                finalSporting: lastResult.sportingScore,
                finalBrand: lastResult.brandScore,
                finalGameday: lastResult.gamedayReadiness,
                finalReliability: lastResult.corvistaReliability,
                findings: findings.map(function(f) { return f.key; }),
                turningPoint: turning,
                avgScore: composite,
                overallScore: composite,
                totalScore: composite,
                composite: composite,
                score: composite,
                performance: band,
                performanceKey: band,
                performanceLabel: t('band_' + band),
                insights
            };
        }

        formatCompletionMessage(summary) {
            const t = window.mySimulation.t.bind(window.mySimulation);
            const s = summary || {};
            const band = s.performanceKey || s.performance || 'atrisk';
            let html = '<div class="cascadia-sim-completion">';
            html += '<h3 class="cascadia-sim-completion-title">' + t('completion_title') + '</h3>';
            html += '<p class="cascadia-sim-completion-score"><strong>' + t('completion_score_label') + '</strong> ' +
                    (s.overallScore || 0) + ' / 100 &mdash; ' + (s.performanceLabel || t('band_' + band)) + '</p>';
            html += '<p>' + t('completion_kpis')
                        .replace('{val}', Math.round(s.finalValuation || 0))
                        .replace('{ebitda}', Math.round(s.ebitda || 0)) + '</p>';
            if (s.finalStms !== undefined) {
                html += '<p>' + t('completion_strip')
                            .replace('{stms}', Math.round(s.finalStms || 0).toLocaleString())
                            .replace('{sport}', Math.round(s.finalSporting || 0))
                            .replace('{brand}', Math.round(s.finalBrand || 0))
                            .replace('{gameday}', Math.round(s.finalGameday || 0))
                            .replace('{corvista}', Math.round(s.finalReliability || 0)) + '</p>';
            }
            const tp = s.turningPoint;
            if (tp && tp.best && tp.worst) {
                html += '<p><strong>' + t('turning_title') + '</strong> ' + t('turning_text')
                            .replace('{best}', tp.best.window)
                            .replace('{bestChoice}', this._getChoiceLabel(tp.best.choice))
                            .replace('{bestDelta}', this._fmtDelta(tp.best.delta))
                            .replace('{worst}', tp.worst.window)
                            .replace('{worstChoice}', this._getChoiceLabel(tp.worst.choice))
                            .replace('{worstDelta}', this._fmtDelta(tp.worst.delta)) + '</p>';
            }
            const ins = s.insights || [];
            if (ins.length) {
                html += '<ul class="cascadia-sim-completion-insights">';
                for (let i = 0; i < ins.length; i++) html += '<li>' + ins[i] + '</li>';
                html += '</ul>';
            }
            html += '<p><strong>' + t('dq_title') + '</strong></p><ol class="cascadia-sim-completion-questions">';
            html += '<li>' + t('dq1') + '</li><li>' + t('dq2') + '</li><li>' + t('dq3') + '</li></ol>';
            html += '</div>';
            return html;
        }

